from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any, Iterable


def _normalize_names(values: Iterable[str]) -> tuple[str, ...]:
    normalized: list[str] = []
    seen: set[str] = set()

    for value in values:
        cleaned = value.strip()
        if not cleaned or cleaned in seen:
            continue
        normalized.append(cleaned)
        seen.add(cleaned)

    return tuple(normalized)


@dataclass(frozen=True, slots=True)
class RBACPrincipal:
    subject: str | None = None
    email: str | None = None
    display_name: str | None = None
    groups: tuple[str, ...] = ()
    roles: tuple[str, ...] = ()
    raw_claims: dict[str, Any] = field(default_factory=dict, repr=False, compare=False)

    def __post_init__(self) -> None:
        object.__setattr__(self, "groups", _normalize_names(self.groups))
        object.__setattr__(self, "roles", _normalize_names(self.roles))
        object.__setattr__(self, "raw_claims", dict(self.raw_claims))

    @property
    def is_authenticated(self) -> bool:
        return bool(self.subject and self.subject.strip())

    def has_role(self, role: str) -> bool:
        candidate = role.strip()
        return bool(candidate) and candidate in self.roles

    def has_any_role(self, roles: Iterable[str]) -> bool:
        requested = {role.strip() for role in roles if role and role.strip()}
        return bool(requested.intersection(self.roles))

    def to_response_payload(self, *, include_claims: bool = False) -> dict[str, Any]:
        payload: dict[str, Any] = {
            "authenticated": self.is_authenticated,
            "subject": self.subject,
            "email": self.email,
            "display_name": self.display_name,
            "groups": list(self.groups),
            "roles": list(self.roles),
        }
        if include_claims:
            payload["raw_claims"] = dict(self.raw_claims)
        return payload


@dataclass(frozen=True, slots=True)
class AuthorizationDecision:
    allowed: bool
    reason: str
    required_roles: tuple[str, ...] = ()
    granted_roles: tuple[str, ...] = ()
    subject: str | None = None

    def to_log_payload(self) -> dict[str, Any]:
        return {
            "allowed": self.allowed,
            "reason": self.reason,
            "required_roles": list(self.required_roles),
            "granted_roles": list(self.granted_roles),
            "subject": self.subject,
        }
