from __future__ import annotations

import os
from dataclasses import dataclass, field
from typing import Iterable, Mapping


def _parse_bool(value: str | None, default: bool) -> bool:
    if value is None:
        return default
    return value.strip().lower() in {"1", "true", "yes", "on"}


def _parse_csv(value: str | None, default: Iterable[str]) -> tuple[str, ...]:
    if value is None:
        return tuple(default)

    items: list[str] = []
    seen: set[str] = set()

    for raw in value.split(","):
        cleaned = raw.strip()
        if not cleaned or cleaned in seen:
            continue
        items.append(cleaned)
        seen.add(cleaned)

    return tuple(items)


def _parse_group_role_map(
    value: str | None,
    default: Mapping[str, tuple[str, ...]],
) -> dict[str, tuple[str, ...]]:
    if value is None:
        return {role: tuple(groups) for role, groups in default.items()}

    role_map: dict[str, tuple[str, ...]] = {}
    entries = [entry.strip() for entry in value.split(";") if entry.strip()]

    for entry in entries:
        if "=" not in entry:
            continue
        role_name, raw_groups = entry.split("=", 1)
        role = role_name.strip()
        if not role:
            continue
        groups = _parse_csv(raw_groups, ())
        if groups:
            role_map[role] = groups

    return role_map


@dataclass(frozen=True, slots=True)
class AuthzSettings:
    enabled: bool = True
    subject_claim: str = "sub"
    email_claim: str = "email"
    display_name_claim: str = "name"
    group_claim_candidates: tuple[str, ...] = ("groups", "group", "cognito:groups")
    role_claim_candidates: tuple[str, ...] = ("roles", "role")
    claim_container_candidates: tuple[str, ...] = ("claims", "user")
    default_roles: tuple[str, ...] = ()
    group_role_map: dict[str, tuple[str, ...]] = field(default_factory=dict)
    debug_include_claims: bool = False
    dev_claims_header: str = "X-Auth-Claims"
    dev_subject_header: str = "X-Auth-Subject"
    dev_email_header: str = "X-Auth-Email"
    dev_name_header: str = "X-Auth-Name"
    dev_groups_header: str = "X-Auth-Groups"

    @classmethod
    def from_env(
        cls,
        environ: Mapping[str, str] | None = None,
        *,
        prefix: str = "AUTHZ_",
    ) -> "AuthzSettings":
        env = dict(os.environ if environ is None else environ)

        return cls(
            enabled=_parse_bool(env.get(f"{prefix}ENABLED"), True),
            subject_claim=env.get(f"{prefix}SUBJECT_CLAIM", "sub").strip() or "sub",
            email_claim=env.get(f"{prefix}EMAIL_CLAIM", "email").strip() or "email",
            display_name_claim=env.get(f"{prefix}DISPLAY_NAME_CLAIM", "name").strip() or "name",
            group_claim_candidates=_parse_csv(
                env.get(f"{prefix}GROUP_CLAIM_CANDIDATES"),
                ("groups", "group", "cognito:groups"),
            ),
            role_claim_candidates=_parse_csv(
                env.get(f"{prefix}ROLE_CLAIM_CANDIDATES"),
                ("roles", "role"),
            ),
            claim_container_candidates=_parse_csv(
                env.get(f"{prefix}CLAIM_CONTAINER_CANDIDATES"),
                ("claims", "user"),
            ),
            default_roles=_parse_csv(env.get(f"{prefix}DEFAULT_ROLES"), ()),
            group_role_map=_parse_group_role_map(env.get(f"{prefix}GROUP_ROLE_MAP"), {}),
            debug_include_claims=_parse_bool(env.get(f"{prefix}DEBUG_INCLUDE_CLAIMS"), False),
            dev_claims_header=env.get(f"{prefix}DEV_CLAIMS_HEADER", "X-Auth-Claims").strip() or "X-Auth-Claims",
            dev_subject_header=env.get(f"{prefix}DEV_SUBJECT_HEADER", "X-Auth-Subject").strip() or "X-Auth-Subject",
            dev_email_header=env.get(f"{prefix}DEV_EMAIL_HEADER", "X-Auth-Email").strip() or "X-Auth-Email",
            dev_name_header=env.get(f"{prefix}DEV_NAME_HEADER", "X-Auth-Name").strip() or "X-Auth-Name",
            dev_groups_header=env.get(f"{prefix}DEV_GROUPS_HEADER", "X-Auth-Groups").strip() or "X-Auth-Groups",
        )

    def resolve_roles(
        self,
        *,
        groups: Iterable[str] = (),
        explicit_roles: Iterable[str] = (),
    ) -> tuple[str, ...]:
        resolved: list[str] = []
        seen: set[str] = set()

        for role in explicit_roles:
            cleaned = role.strip()
            if cleaned and cleaned not in seen:
                resolved.append(cleaned)
                seen.add(cleaned)

        normalized_groups = {group.strip() for group in groups if group and group.strip()}

        for app_role, mapped_groups in self.group_role_map.items():
            if normalized_groups.intersection(mapped_groups) and app_role not in seen:
                resolved.append(app_role)
                seen.add(app_role)

        for role in self.default_roles:
            cleaned = role.strip()
            if cleaned and cleaned not in seen:
                resolved.append(cleaned)
                seen.add(cleaned)

        return tuple(resolved)
