from __future__ import annotations

from collections.abc import Mapping, Sequence
from typing import Any

from .models import RBACPrincipal
from .settings import AuthzSettings


def _stringify(value: Any) -> str | None:
    if value is None:
        return None
    if isinstance(value, str):
        cleaned = value.strip()
        return cleaned or None
    cleaned = str(value).strip()
    return cleaned or None


def normalize_multi_value_claim(value: Any) -> tuple[str, ...]:
    if value is None:
        return ()

    values: list[str] = []
    seen: set[str] = set()

    if isinstance(value, str):
        candidates = value.split(",")
    elif isinstance(value, Mapping):
        if "items" in value:
            return normalize_multi_value_claim(value["items"])
        if "values" in value:
            return normalize_multi_value_claim(value["values"])
        candidates = list(value.values())
    elif isinstance(value, Sequence):
        candidates = list(value)
    else:
        candidates = [value]

    for candidate in candidates:
        text = _stringify(candidate)
        if not text:
            continue
        for part in text.split(","):
            cleaned = part.strip()
            if not cleaned or cleaned in seen:
                continue
            values.append(cleaned)
            seen.add(cleaned)

    return tuple(values)


def extract_nested_claims(
    payload: Mapping[str, Any] | None,
    container_candidates: Sequence[str],
) -> dict[str, Any]:
    if not isinstance(payload, Mapping):
        return {}

    for key in container_candidates:
        nested = payload.get(key)
        if isinstance(nested, Mapping):
            return dict(nested)

    return dict(payload)


def _extract_first_present(claims: Mapping[str, Any], candidates: Sequence[str]) -> Any:
    for key in candidates:
        if key in claims:
            return claims[key]
    return None


def build_principal_from_claims(
    claims: Mapping[str, Any] | None,
    settings: AuthzSettings,
) -> RBACPrincipal:
    normalized_claims = extract_nested_claims(claims, settings.claim_container_candidates)

    subject = _stringify(normalized_claims.get(settings.subject_claim))
    email = _stringify(normalized_claims.get(settings.email_claim))
    display_name = _stringify(normalized_claims.get(settings.display_name_claim))

    groups = normalize_multi_value_claim(
        _extract_first_present(normalized_claims, settings.group_claim_candidates),
    )
    explicit_roles = normalize_multi_value_claim(
        _extract_first_present(normalized_claims, settings.role_claim_candidates),
    )
    resolved_roles = settings.resolve_roles(groups=groups, explicit_roles=explicit_roles)

    return RBACPrincipal(
        subject=subject,
        email=email,
        display_name=display_name,
        groups=groups,
        roles=resolved_roles,
        raw_claims=normalized_claims,
    )
