from __future__ import annotations

import logging
from typing import Any

from .models import AuthorizationDecision, RBACPrincipal

LOGGER_NAME = "shared.authz"


def get_authz_logger() -> logging.Logger:
    return logging.getLogger(LOGGER_NAME)


def build_authz_log_payload(
    *,
    decision: AuthorizationDecision,
    principal: RBACPrincipal,
    path: str | None = None,
    method: str | None = None,
) -> dict[str, Any]:
    payload = decision.to_log_payload()
    payload.update(
        {
            "path": path,
            "method": method,
            "authenticated": principal.is_authenticated,
            "principal_roles": list(principal.roles),
            "principal_groups": list(principal.groups),
        },
    )
    return payload


def log_authz_decision(
    *,
    decision: AuthorizationDecision,
    principal: RBACPrincipal,
    path: str | None = None,
    method: str | None = None,
    logger: logging.Logger | None = None,
) -> None:
    active_logger = logger or get_authz_logger()
    payload = build_authz_log_payload(
        decision=decision,
        principal=principal,
        path=path,
        method=method,
    )
    active_logger.info("authz.decision", extra={"authz": payload})
