from __future__ import annotations

import json
from collections.abc import Mapping
from typing import Any

from fastapi import Depends, HTTPException, Request, status

from .claims import build_principal_from_claims, extract_nested_claims, normalize_multi_value_claim
from .logging import log_authz_decision
from .models import AuthorizationDecision, RBACPrincipal
from .settings import AuthzSettings

SESSION_CLAIMS_STATE_KEY = "session_claims"
SESSION_PRINCIPAL_STATE_KEY = "authz_principal"


def get_authz_settings(request: Request) -> AuthzSettings:
    configured = getattr(request.app.state, "authz_settings", None)
    if isinstance(configured, AuthzSettings):
        return configured
    return AuthzSettings.from_env()


def _get_session_payload(request: Request) -> Mapping[str, Any] | None:
    try:
        session = request.session
    except AssertionError:
        return None

    if isinstance(session, Mapping):
        return session
    return None


def _parse_json_claims_header(raw_value: str | None) -> dict[str, Any]:
    if not raw_value:
        return {}

    try:
        parsed = json.loads(raw_value)
    except json.JSONDecodeError:
        return {}

    if isinstance(parsed, Mapping):
        return dict(parsed)

    return {}


def resolve_request_claims(request: Request, settings: AuthzSettings) -> dict[str, Any]:
    cached_claims = getattr(request.state, SESSION_CLAIMS_STATE_KEY, None)
    if isinstance(cached_claims, Mapping):
        return extract_nested_claims(cached_claims, settings.claim_container_candidates)

    state_claims = getattr(request.state, "claims", None)
    if isinstance(state_claims, Mapping):
        resolved_state_claims = extract_nested_claims(state_claims, settings.claim_container_candidates)
        setattr(request.state, SESSION_CLAIMS_STATE_KEY, resolved_state_claims)
        return resolved_state_claims

    session_payload = _get_session_payload(request)
    if isinstance(session_payload, Mapping):
        resolved_session_claims = extract_nested_claims(session_payload, settings.claim_container_candidates)
        if resolved_session_claims:
            setattr(request.state, SESSION_CLAIMS_STATE_KEY, resolved_session_claims)
            return resolved_session_claims

    header_claims = _parse_json_claims_header(request.headers.get(settings.dev_claims_header))
    if header_claims:
        setattr(request.state, SESSION_CLAIMS_STATE_KEY, header_claims)
        return header_claims

    fallback_claims: dict[str, Any] = {}
    subject = request.headers.get(settings.dev_subject_header)
    email = request.headers.get(settings.dev_email_header)
    display_name = request.headers.get(settings.dev_name_header)
    groups = normalize_multi_value_claim(request.headers.get(settings.dev_groups_header))

    if subject:
        fallback_claims[settings.subject_claim] = subject
    if email:
        fallback_claims[settings.email_claim] = email
    if display_name:
        fallback_claims[settings.display_name_claim] = display_name
    if groups:
        fallback_claims[settings.group_claim_candidates[0]] = list(groups)

    setattr(request.state, SESSION_CLAIMS_STATE_KEY, fallback_claims)
    return fallback_claims


def get_current_principal(
    request: Request,
    settings: AuthzSettings = Depends(get_authz_settings),
) -> RBACPrincipal:
    cached_principal = getattr(request.state, SESSION_PRINCIPAL_STATE_KEY, None)
    if isinstance(cached_principal, RBACPrincipal):
        return cached_principal

    claims = resolve_request_claims(request, settings)
    principal = build_principal_from_claims(claims, settings)
    setattr(request.state, SESSION_PRINCIPAL_STATE_KEY, principal)
    return principal


def require_roles(*required_roles: str):
    normalized_required = tuple(role.strip() for role in required_roles if role and role.strip())

    def _dependency(
        request: Request,
        settings: AuthzSettings = Depends(get_authz_settings),
        principal: RBACPrincipal = Depends(get_current_principal),
    ) -> RBACPrincipal:
        if not settings.enabled:
            decision = AuthorizationDecision(
                allowed=True,
                reason="authz_disabled",
                required_roles=normalized_required,
                granted_roles=principal.roles,
                subject=principal.subject,
            )
            log_authz_decision(
                decision=decision,
                principal=principal,
                path=request.url.path,
                method=request.method,
            )
            return principal

        if not principal.is_authenticated:
            decision = AuthorizationDecision(
                allowed=False,
                reason="unauthenticated",
                required_roles=normalized_required,
                granted_roles=(),
                subject=principal.subject,
            )
            log_authz_decision(
                decision=decision,
                principal=principal,
                path=request.url.path,
                method=request.method,
            )
            raise HTTPException(
                status_code=status.HTTP_401_UNAUTHORIZED,
                detail={
                    "error": "unauthenticated",
                    "required_roles": list(normalized_required),
                },
            )

        granted_roles = tuple(role for role in principal.roles if role in normalized_required)

        if normalized_required and not granted_roles:
            decision = AuthorizationDecision(
                allowed=False,
                reason="missing_required_role",
                required_roles=normalized_required,
                granted_roles=(),
                subject=principal.subject,
            )
            log_authz_decision(
                decision=decision,
                principal=principal,
                path=request.url.path,
                method=request.method,
            )
            raise HTTPException(
                status_code=status.HTTP_403_FORBIDDEN,
                detail={
                    "error": "forbidden",
                    "required_roles": list(normalized_required),
                    "principal_roles": list(principal.roles),
                },
            )

        decision = AuthorizationDecision(
            allowed=True,
            reason="authorized",
            required_roles=normalized_required,
            granted_roles=granted_roles or principal.roles,
            subject=principal.subject,
        )
        log_authz_decision(
            decision=decision,
            principal=principal,
            path=request.url.path,
            method=request.method,
        )
        return principal

    return _dependency
