from __future__ import annotations

from typing import Annotated, Any

from fastapi import APIRouter, Depends, Request

from shared.authz.dependencies import get_authz_settings, get_current_principal, require_roles, resolve_request_claims
from shared.authz.models import RBACPrincipal
from shared.authz.settings import AuthzSettings

router = APIRouter(prefix="/auth/session-rbac", tags=["auth", "rbac"])


@router.get("/inspect")
def inspect_session_rbac(
    request: Request,
    settings: Annotated[AuthzSettings, Depends(get_authz_settings)],
    principal: Annotated[RBACPrincipal, Depends(get_current_principal)],
) -> dict[str, Any]:
    claims = resolve_request_claims(request, settings)
    payload: dict[str, Any] = {
        "authz_enabled": settings.enabled,
        "authenticated": principal.is_authenticated,
        "subject": principal.subject,
        "email": principal.email,
        "display_name": principal.display_name,
        "groups": list(principal.groups),
        "roles": list(principal.roles),
        "claim_keys": sorted(claims.keys()),
    }

    if settings.debug_include_claims:
        payload["raw_claims"] = claims

    return payload


@router.get("/reviewer-probe")
def reviewer_probe(
    principal: Annotated[RBACPrincipal, Depends(require_roles("reviewer", "admin"))],
) -> dict[str, Any]:
    return {
        "authorized": True,
        "subject": principal.subject,
        "roles": list(principal.roles),
    }
