from shared.authz.claims import build_principal_from_claims, extract_nested_claims, normalize_multi_value_claim
from shared.authz.settings import AuthzSettings


def test_from_env_parses_scalar_and_collection_settings(monkeypatch):
    monkeypatch.setenv("AUTHZ_ENABLED", "false")
    monkeypatch.setenv("AUTHZ_GROUP_CLAIM_CANDIDATES", "groups,teams")
    monkeypatch.setenv("AUTHZ_ROLE_CLAIM_CANDIDATES", "roles,permissions")
    monkeypatch.setenv("AUTHZ_DEFAULT_ROLES", "reader,auditor")
    monkeypatch.setenv(
        "AUTHZ_GROUP_ROLE_MAP",
        "reviewer=reviewers,supervisors;admin=admins",
    )
    monkeypatch.setenv("AUTHZ_DEBUG_INCLUDE_CLAIMS", "true")
    monkeypatch.setenv("AUTHZ_DEV_CLAIMS_HEADER", "X-Debug-Claims")

    settings = AuthzSettings.from_env()

    assert settings.enabled is False
    assert settings.group_claim_candidates == ("groups", "teams")
    assert settings.role_claim_candidates == ("roles", "permissions")
    assert settings.default_roles == ("reader", "auditor")
    assert settings.group_role_map == {
        "reviewer": ("reviewers", "supervisors"),
        "admin": ("admins",),
    }
    assert settings.debug_include_claims is True
    assert settings.dev_claims_header == "X-Debug-Claims"


def test_extract_nested_claims_prefers_configured_container():
    payload = {
        "claims": {
            "sub": "user-1",
            "groups": ["reviewers"],
        },
        "ignored": "value",
    }

    claims = extract_nested_claims(payload, ("claims", "user"))

    assert claims == {"sub": "user-1", "groups": ["reviewers"]}


def test_normalize_multi_value_claim_handles_strings_sequences_and_dict_wrappers():
    assert normalize_multi_value_claim("reviewers, admins ,reviewers") == ("reviewers", "admins")
    assert normalize_multi_value_claim(["reviewers", "admins", "admins"]) == ("reviewers", "admins")
    assert normalize_multi_value_claim({"items": ["reviewers", "admins"]}) == ("reviewers", "admins")
    assert normalize_multi_value_claim(None) == ()


def test_build_principal_combines_explicit_roles_group_mapping_and_defaults():
    settings = AuthzSettings(
        group_role_map={
            "reviewer": ("reviewers",),
            "admin": ("admins",),
        },
        default_roles=("reader",),
    )
    claims = {
        "claims": {
            "sub": "alice",
            "email": "alice@example.com",
            "name": "Alice Reviewer",
            "groups": ["reviewers", "ops"],
            "roles": ["case-worker"],
        },
    }

    principal = build_principal_from_claims(claims, settings)

    assert principal.subject == "alice"
    assert principal.email == "alice@example.com"
    assert principal.display_name == "Alice Reviewer"
    assert principal.groups == ("reviewers", "ops")
    assert principal.roles == ("case-worker", "reviewer", "reader")
    assert principal.is_authenticated is True
