import json

from fastapi import FastAPI
from fastapi.testclient import TestClient

from backend.auth.session_rbac.router import router
from shared.authz.settings import AuthzSettings


def _build_client(settings: AuthzSettings) -> TestClient:
    app = FastAPI()
    app.state.authz_settings = settings
    app.include_router(router)
    return TestClient(app)


def test_inspect_endpoint_resolves_claims_and_roles_from_header_payload():
    settings = AuthzSettings(
        group_role_map={"reviewer": ("reviewers",)},
        debug_include_claims=False,
    )
    client = _build_client(settings)

    response = client.get(
        "/auth/session-rbac/inspect",
        headers={
            settings.dev_claims_header: json.dumps(
                {
                    "sub": "user-123",
                    "email": "user-123@example.com",
                    "name": "Reviewer User",
                    "groups": ["reviewers"],
                },
            ),
        },
    )

    assert response.status_code == 200
    body = response.json()
    assert body["authz_enabled"] is True
    assert body["authenticated"] is True
    assert body["subject"] == "user-123"
    assert body["email"] == "user-123@example.com"
